//! A downstream crate unlike this workspace's own crates: it uses Rust 2021 and
//! denies lints that code generated by `optionize` must not trigger.

#![forbid(unsafe_code)]
#![deny(missing_debug_implementations, unused_qualifications)]

use optionize::optionized;

#[optionized]
#[derive(Debug, Default, PartialEq)]
pub struct Endpoint {
    pub host: String,
    pub port: u16,
}

#[derive(Debug, Default, PartialEq)]
pub struct Seconds(pub u64);

impl From<u64> for Seconds {
    fn from(value: u64) -> Self {
        Self(value)
    }
}

impl From<Seconds> for u64 {
    fn from(value: Seconds) -> Self {
        value.0
    }
}

#[optionized]
#[optionize(partial(upgradable, marked))]
#[derive(Debug, Default, PartialEq)]
pub struct Config<'a, Data: Default> {
    pub name: &'a str,
    pub label: Option<String>,
    #[optionize(flatten)]
    pub verbose: bool,
    #[optionize(nest = EndpointOptional)]
    pub endpoint: Endpoint,
    #[optionize(flatten, nest = EndpointOptional)]
    pub fallback: Endpoint,
    #[optionize(as = u64)]
    pub timeout: Seconds,
    #[optionize(default = |_| 3)]
    pub retries: u8,
    #[optionize(skip)]
    pub data: Data,
}

#[optionized]
#[derive(Debug, PartialEq)]
pub struct Pair(pub u32, pub String);

pub mod external {
    #[derive(Debug, PartialEq)]
    pub struct Peer {
        pub address: String,
        pub weight: Option<u32>,
    }

    #[derive(Debug, Default)]
    pub struct WirePatch {
        pub value: Option<u32>,
    }
}

#[optionized]
#[optionize(subject = external::Peer)]
#[derive(Debug, Default)]
pub struct PeerPatch {
    #[optionize(name = "address")]
    pub host: Option<String>,
    pub weight: Option<Option<u32>>,
}

#[optionized]
#[optionize(object = external::WirePatch)]
#[derive(Debug, PartialEq)]
pub struct Wire {
    pub value: u32,
}
